  ('EMERGENCY_FUND_BUILD', 1, 'emergency_fund', 'Build an emergency fund', 'Liquid savings cover fewer months of essential expenses than the target.', '{"base_target_months": 3, "build_months": 12, "elevated_target_months": 6, "high_priority_below_months": 1, "max_share_of_capacity": "0.50"}'::jsonb),
  ('GOAL_SAVINGS_INCREASE', 1, 'goal_savings', 'Increase savings toward a goal', 'A dated goal needs more per month than is currently planned.', '{"high_priority_goal_rank": 1, "high_priority_within_months": 12}'::jsonb),
  ('DISCRETIONARY_SPENDING_REVIEW', 1, 'discretionary_spending', 'Review high discretionary spending', 'Discretionary spending is a large share of expenses or rose sharply.', '{"illustrative_reduction_pct": "10", "share_threshold_pct": "35", "spike_min_increase": "2000", "spike_ratio": "1.25"}'::jsonb),
  ('UPCOMING_OBLIGATIONS_PREPARE', 1, 'upcoming_obligations', 'Prepare for upcoming obligations', 'Known non-monthly or large obligations are due within 30 days.', '{"balance_share_threshold": "0.50", "horizon_days": 30}'::jsonb),
  ('RECURRING_EXPENSES_REVIEW', 1, 'recurring_expenses', 'Review recurring subscriptions', 'Several recurring subscription charges were detected.', '{"income_share_threshold_pct": "3", "min_monthly_total": "1500", "min_subscriptions": 3}'::jsonb),
  ('CASH_FLOW_CONSISTENCY', 1, 'cash_flow_consistency', 'Improve cash-flow consistency', 'Spending exceeded income in recent months or income is highly variable.', '{"income_cv_threshold": "0.25", "lookback_months": 3, "negative_months_threshold": 2}'::jsonb),
  ('GOAL_PROGRESS_CELEBRATE', 1, 'goal_celebration', 'Celebrate goal progress', 'A goal has reached a 50%, 75% or 100% milestone.', '{"milestones_pct": [50, 75, 100]}'::jsonb)
